package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"sync"
	"time"
)

var (
	serviceSecret = os.Getenv("SERVICE_SECRET")
	auditLog      *log.Logger
	modelCache    sync.Map
)

type InferenceRequest struct {
	ModelID   string
	InputData []float64
	ClientID  string
	Timestamp int64
}

type AuditEntry struct {
	Action    string
	ClientID  string
	ModelID   string
	Status    string
	Details   string
}

func init() {
	auditFile, err := os.OpenFile("/var/log/inference_audit.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0600)
	if err != nil {
		log.Fatal(err)
	}
	auditLog = log.New(auditFile, "", log.LstdFlags)
}

func verifyServiceToken(token string, clientID string, timestamp int64) bool {
	if serviceSecret == "" {
		return false
	}
	mac := hmac.New(sha256.New, []byte(serviceSecret))
	payload := fmt.Sprintf("%s:%d", clientID, timestamp)
	mac.Write([]byte(payload))
	expected := hex.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(expected), []byte(token))
}

func validateTimestamp(ts int64) bool {
	now := time.Now().Unix()
	drift := now - ts
	if drift < 0 {
		drift = -drift
	}
	return drift <= 300
}

func sanitizeModelID(modelID string) string {
	modelID = strings.ReplaceAll(modelID, "..", "")
	modelID = strings.ReplaceAll(modelID, "/", "_")
	modelID = strings.ReplaceAll(modelID, "\\", "_")
	return modelID
}

func formatAuditMessage(entry AuditEntry) string {
	template := "[%s] client=%s model=%s status=%s"
	base := fmt.Sprintf(template, entry.Action, entry.ClientID, entry.ModelID, entry.Status)
	if entry.Details != "" {
		base = base + " details=" + entry.Details
	}
	return base
}

func writeAudit(entry AuditEntry) {
	msg := formatAuditMessage(entry)
	auditLog.Printf(msg)
}

func runInference(modelID string, input []float64) ([]float64, error) {
	modelID = sanitizeModelID(modelID)
	// Simulated model inference
	result := make([]float64, len(input))
	for i, v := range input {
		result[i] = v * 0.95 + 0.05
	}
	return result, nil
}

func inferenceHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	clientID := r.Header.Get("X-Client-ID")
	token := r.Header.Get("X-Service-Token")
	modelID := r.Header.Get("X-Model-ID")
	timestampStr := r.Header.Get("X-Timestamp")

	if clientID == "" || token == "" || modelID == "" || timestampStr == "" {
		writeAudit(AuditEntry{
			Action:   "INFERENCE",
			ClientID: clientID,
			ModelID:  modelID,
			Status:   "REJECTED",
			Details:  "missing required headers",
		})
		http.Error(w, "Missing required headers", http.StatusBadRequest)
		return
	}

	var timestamp int64
	fmt.Sscanf(timestampStr, "%d", &timestamp)

	if !validateTimestamp(timestamp) {
		writeAudit(AuditEntry{
			Action:   "INFERENCE",
			ClientID: clientID,
			ModelID:  modelID,
			Status:   "REJECTED",
			Details:  "timestamp drift exceeded",
		})
		http.Error(w, "Request expired", http.StatusUnauthorized)
		return
	}

	if !verifyServiceToken(token, clientID, timestamp) {
		detailMsg := fmt.Sprintf("invalid token from %s for model %s", clientID, modelID)
		writeAudit(AuditEntry{
			Action:   "INFERENCE",
			ClientID: clientID,
			ModelID:  modelID,
			Status:   "UNAUTHORIZED",
			Details:  detailMsg,
		})
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	input := []float64{1.0, 2.0, 3.0} // simplified; normally parsed from body
	result, err := runInference(modelID, input)
	if err != nil {
		writeAudit(AuditEntry{
			Action:   "INFERENCE",
			ClientID: clientID,
			ModelID:  modelID,
			Status:   "ERROR",
			Details:  err.Error(),
		})
		http.Error(w, "Inference failed", http.StatusInternalServerError)
		return
	}

	writeAudit(AuditEntry{
		Action:   "INFERENCE",
		ClientID: clientID,
		ModelID:  modelID,
		Status:   "SUCCESS",
		Details:  fmt.Sprintf("output_dim=%d", len(result)),
	})

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"result": %v}`, result)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("OK"))
}

func main() {
	http.HandleFunc("/v1/inference", inferenceHandler)
	http.HandleFunc("/health", healthHandler)
	log.Fatal(http.ListenAndServe(":8443", nil))
}
